class Solution:
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        count = Counter(nums)
        buckets = [[] for _ in range(len(nums) + 1)]   # buckets[f]: values that occur f times
        for value, freq in count.items():
            buckets[freq].append(value)
        res = []
        for freq in range(len(buckets) - 1, 0, -1):    # most frequent first
            for value in buckets[freq]:
                res.append(value)
                if len(res) == k:
                    return res
        return res
